const crypto = require('crypto');
const headers = $json.headers ?? {};
const tokenHeader = String(headers['x-govhub-token'] || headers['X-GOVHUB-TOKEN'] || '').trim();
const allowed = String($env.GOVHUB_TOKENS || '').split(',').map(v => v.trim()).filter(Boolean);
if (!tokenHeader || !allowed.includes(tokenHeader)) { return [{json:{ok:false,statusCode:401,error_code:'AUTH_INVALID_TOKEN',message:'invalid token'}}]; }
let scopes = [];
let scopeMapConfigured = false;
try {
  const m = JSON.parse(String($env.GOVHUB_TOKEN_SCOPES_JSON || '{}'));
  scopeMapConfigured = !!m && typeof m === 'object' && Object.keys(m).length > 0;
  if (Array.isArray(m[tokenHeader])) scopes = m[tokenHeader].map((s) => String(s).trim());
} catch {}
if (scopeMapConfigured && !(scopes.includes('s:w') || scopes.includes('snapshots:write'))) { return [{json:{ok:false,statusCode:403,error_code:'AUTH_SCOPE_REQUIRED',message:'missing write scope'}}]; }
let body = $json.body ?? {};
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {}; } }
const required = ['mission_id','udn_mission','tdv_version','created_by'];
for (const k of required) { if (!body[k] || String(body[k]).trim() === '') { return [{json:{ok:false,statusCode:400,error_code:'MISSIONS_REGISTER_INVALID',message:'missing field: '+k}}]; } }
const controlIn = (body.autofix_control && typeof body.autofix_control === 'object') ? body.autofix_control : {};
const enabled = controlIn.enabled === undefined ? true : !!controlIn.enabled;
const max_rounds_raw = Number(controlIn.max_rounds === undefined ? 2 : controlIn.max_rounds);
const max_rounds = Number.isFinite(max_rounds_raw) ? Math.max(1, Math.min(2, Math.trunc(max_rounds_raw))) : 2;
const on_exhaust = String(controlIn.on_exhaust || 'pause_owner').trim() || 'pause_owner';
if (!['pause_owner'].includes(on_exhaust)) { return [{json:{ok:false,statusCode:400,error_code:'AUTOFIX_CONTROL_INVALID',message:'on_exhaust must be pause_owner'}}]; }
let canonical = String(body.udn_mission).split('\r\n').join('\n').split('\n').map(x => x.trim()).filter(Boolean).join('\n');
if (!canonical) { return [{json:{ok:false,statusCode:400,error_code:'UDN_INVALID',message:'udn_mission empty after canonicalization'}}]; }
canonical = canonical.split('\n').filter((line) => !line.startsWith('#af:')).join('\n');
const af_line = '#af:enabled=' + String(enabled) + ';max_rounds=' + String(max_rounds) + ';on_exhaust=' + on_exhaust;
canonical = [canonical, af_line].filter(Boolean).join('\n');
const integrity_hash = crypto.createHash('sha256').update(Buffer.from(canonical,'utf8')).digest('hex');
const esc = (v) => String(v ?? '').replace(/'/g, "''");
return [{json:{ok:true, mission_id:String(body.mission_id), mission_id_sql:esc(body.mission_id), udn_mission:canonical, udn_mission_sql:esc(canonical), tdv_version:String(body.tdv_version), tdv_version_sql:esc(body.tdv_version), created_by:String(body.created_by), created_by_sql:esc(body.created_by), integrity_hash, integrity_hash_sql:esc(integrity_hash), branch:String(body.branch || 'main'), branch_sql:esc(body.branch || 'main'), agent_id:String(body.agent_id || 'CPP'), agent_id_sql:esc(body.agent_id || 'CPP'), autofix_control:{enabled,max_rounds,on_exhaust}}}];
